// Случаи для проверки конфигурации: каждое правило должно сработать хотя бы раз (генератор печатает непокрытые id).
const wf = (body) => ({ '.github/workflows/ci.yml': body });
const job = (steps, extra = '') => `on: push\njobs:\n  j:\n    runs-on: ubuntu-latest\n${extra}    steps:\n${steps}`;
const checkout = '      - uses: actions/checkout@v5\n';
const run = (line) => job(`${checkout}      - run: ${line}\n`);
const inImage = (image, line) => job(`${checkout}      - run: ${line}\n`, `    container: ${image}\n`);

